mapper.sql:
		WHERE od.ENT_CODE = #{srchEntCode}
		AND od.BL_TYPE_MH = 'H'

		AND 1 = 0


			AND od.DELIVERY_CODE = #{srchDeliveryCode}



		AND od.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}


			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP'
			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'


		AND ISNULL(od.CONSOL_YN,'N') = #{srchConsolYn}




			AND ISNULL(ad.PRINT_YN, 'N') = 'N'


			AND ad.PRINT_YN = #{srchPrintYn}




		AND od.CD_TYPE = #{srchCdType}



		AND (1 = 0



			OR od.CD_TYPE = #{item}


			OR od.CD_TYPE IN ('N', 'B') OR ad.DROP_YN = 'Y'



		)  


		AND (od.CD_TYPE IN ('N', 'B') OR ad.DROP_YN = 'Y')




			AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
			AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})


			AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
			AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})




		AND(


				ad.CARRYIN_DATE IS NOT NULL
				ad.CARRYIN_DATE IS NULL
				ad.CARRYOUT_DATE IS NOT NULL
				ad.CARRYOUT_DATE IS NULL
				(ad.CARRYIN_DATE IS NOT NULL AND ad.CARRYOUT_DATE IS NULL)


		)


		AND (ad.SMS_INFORM_YN = 'Y' AND (ad.SMS_INFORM_RES_YN IS NULL OR ad.SMS_INFORM_RES_YN = 'N'))


		AND (ad.SMS_INFORM_YN IS NULL OR ad.SMS_INFORM_YN = '' OR ad.SMS_INFORM_YN = 'N')


		AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'Y')


		AND (ad.SMS_INFORM_YN = 'Y' AND ad.SMS_INFORM_RES_YN = 'N')























		AND ad.CUSTOMS_ID_VERIFY = #{srchCusIdVerify}


		AND ad.CUSTOMS_ID_VERIFY IN (#{item})







				AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) LIKE CONCAT('%',#{srchNo},'%')




						AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) IN (#{item})


						AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) = #{srchNo}








					AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')




							AND ${srchNoType} IN (#{item})


							AND ${srchNoType} = #{srchNo}








		AND od.OD_JOB_NO IN (#{item})









			AND od.CUST_CODE_LV1 = #{srchCustomerCode}



			AND od.CUST_CODE_LV2 = #{srchCustomerCode}








			AND 1 = 0


			AND od.CUST_CODE_LV${loginCustomerUpperLev} = #{srchCustomerCode}








			AND 1 = 0


			AND od.CUST_CODE_LV${loginCustomerLowLev} = #{srchCustomerCode}














			AND (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) LIKE CONCAT('%',#{srchCustomerName},'%')



			AND (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) LIKE CONCAT('%',#{srchCustomerName},'%')








			AND 1 = 0


			AND (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV${loginCustomerUpperLev}) LIKE CONCAT('%',#{srchCustomerName},'%')








			AND 1 = 0


			AND (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV${loginCustomerLowLev}) LIKE CONCAT('%',#{srchCustomerName},'%')








			AND (SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = od.REGISTER_USER_ID) LIKE CONCAT('%',#{srchRegisterUserName},'%')






			AND(1 = 0

			OR od.INSPECTION_YN = #{srchInspectionYn}


			OR ad.SE_INSPECTION_YN = #{srchSeInspectionYn}


			OR ad.XRAY_YN = #{srchXrayYn}


			OR ad.DROP_YN = #{srchDropYn}


			OR ad.SIMPLE_EDI_STATUS = #{srchSimpleEdiStatus}


			OR ad.SIMPLE_STATEMENT_YN = #{srchSimpleStatementYn}


			OR (ISNULL(od.CLEARANCE_VIOLATION_CODE, '') != '' OR ISNULL(od.CLEARANCE_VIOLATION_REASON, '') != '')
        	OR (SELECT COUNT(*) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') > 0


			AND ISNULL((SELECT TOP 1 ABNORMAL_CODE FROM TB_ECM_OD_ABNORMAL WHERE OD_JOB_NO = od.OD_JOB_NO),'') != ''

			)




        AND ad.LAST_POD_STATUS < 'ECM010'


        AND ad.LAST_POD_STATUS >= 'ECM010'




		AND ad.LAST_POD_STATUS = #{srchStatus}


		AND ad.LAST_POD_STATUS IN (#{item})


		AND ad.LAST_POD_STATUS NOT IN (#{item})


		AND ad.LAST_POD_STATUS = 'ECM040'




			AND od.MULTI_YN = 'Y'


			AND ISNULL(od.MULTI_YN, 'N') = 'N'
-- 				AND od.PIECES > 1




			AND od.RETURN_YN = #{srchReturnYn}




					AND (od.RETURN_YN = 'Y' AND ISNULL(od.RETURN_DELIVERY_NO,'') != '')   


					AND (od.RETURN_YN = 'Y' AND ISNULL(od.RETURN_DELIVERY_NO,'') = '')

