mapper.insert:
/* OrderCustomerMapper.insertOrder : Order Insert */ INSERT INTO TB_ECM_OD ( OD_JOB_NO ,ENT_CODE ,ENT_BUSINESS_CODE ,SOLUTION ,BOUND ,BOUND_TYPE ,PO_DATE ,PO_NO ,CUST_CODE_LV1 ,CUST_CODE_LV2 ,CUST_CODE_LV3 ,CUST_CODE_LV4 ,CUST_CODE_LV5 ,CUST_CODE_LV6 ,CUST_CODE_LV7 ,BL_TYPE_MH ,CONSOL_YN ,MBL_NO ,HBL_NO ,DELIVERY_CODE ,DELIVERY_NOTE ,CB_CODE ,CB_NAME ,CD_TYPE ,CD_USE_TYPE ,ECM_TYPE ,CUSTOMS_ID_TYPE ,CLEARANCE_VIOLATION_CODE ,CLEARANCE_VIOLATION_REASON ,URL ,VESSEL_FLIGHT ,PIECES ,PIECES_REAL ,GWT ,GWT_LBS ,CBM ,VWT ,COMMODITY_ITEM ,CURRENCY_CODE ,EXCHANGE_RATE ,AMOUNT_LOC ,AMOUNT_CUR ,SHIPPER_CODE ,SHIPPER_NAME ,SHIPPER_ADDRESS ,SHIPPER_ADDRESS_A ,SHIPPER_ADDRESS_B ,SHIPPER_ADDRESS_C ,SHIPPER_ADDRESS_D ,SHIPPER_TEL ,SHIPPER_ZIPCODE ,SHIPPER_COUNTRY_CODE ,SHIPPER_STATE_CODE ,SHIPPER_PLACE_CODE ,SHIPPER_PLACE ,SHIPPER_STREET ,SHIPPER_BUSINESS_ID ,SHIPPER_ATTN_ID ,SHIPPER_ATTN ,SHIPPER_FAX ,CONSIGNEE_CODE ,CONSIGNEE_NAME ,CONSIGNEE_ADDRESS ,CONSIGNEE_ADDRESS_A ,CONSIGNEE_ADDRESS_B ,CONSIGNEE_ADDRESS_C ,CONSIGNEE_ADDRESS_D ,CONSIGNEE_ZIPCODE ,CONSIGNEE_COUNTRY_CODE ,CONSIGNEE_STATE_CODE ,CONSIGNEE_PLACE_CODE ,CONSIGNEE_PLACE ,CONSIGNEE_STREET ,CONSIGNEE_BUSINESS_ID ,CONSIGNEE_ATTN_ID ,CONSIGNEE_ATTN ,CONSIGNEE_FAX ,CONSIGNEE_NAME_LOC ,CONSIGNEE_ADDRESS_LOC ,INSPECTION_TYPE ,FTA_YN ,FTA_REMARKS ,REMARKS ,AGENT_REG_NO ,AGENT_NAME ,SELLER_REG_NO ,SELLER_NAME ,SALES_BROKER_REG_NO ,SALES_BROKER_NAME ,ALLOWED_ITEM_CODE ,ORIG_COUNTRY ,DIM_WIDTH ,DIM_LENGTH ,DIM_HEIGHT ,INPUT_METHOD ,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME
,CONSIGNEE_HP_ENC ,CONSIGNEE_TEL_ENC ,CUSTOMS_ID_ENC
,CONSIGNEE_HP ,CONSIGNEE_TEL ,CUSTOMS_ID
,CONSIGNEE_LAST_NAME ,CONSIGNEE_FIRST_NAME ,DEST_DELIVERY_NO ,FORWARD_AGENT_CODE ,FORWARD_AGENT_NAME ,ORDER_NAME ,ORDER_TEL ,ORDER_ACCOUNT ,ECM_YN ) VALUES ( #{odJobNo} ,#{entCode} ,(SELECT TOP 1 ENT_BUSINESS_CODE FROM TB_SMS_ENT_BUSINESS WHERE HEAD_BUSINESS_YN = 'Y') ,#{solution}
,#{bound} ,#{boundType} ,CONVERT(DATE, #{poDate}, ${dateFormat}) ,LTRIM(RTRIM(#{poNo})) ,#{custCodeLv1} ,#{custCodeLv2} ,#{custCodeLv3} ,#{custCodeLv4} ,#{custCodeLv5} ,#{custCodeLv6} ,#{custCodeLv7} ,#{blTypeMh} ,#{consolYn} ,LTRIM(RTRIM(REPLACE(#{mblNo},char(9),''))) ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),''))) ,#{deliveryCode} ,#{deliveryNote} ,#{cbCode} ,#{cbName} ,#{cdType} ,#{cdUseType} ,#{ecmType} ,#{customsIdType} ,#{clearanceViolationCode} ,#{clearanceViolationReason} ,#{url} ,#{vesselFlight} ,#{pieces} ,#{piecesReal} ,#{gwt} ,#{gwtLbs}
,#{cbm} ,#{vwt} ,UPPER(#{commodityItem}) ,#{currencyCode} ,#{exchangeRate} ,#{amountLoc} ,#{amountCur} ,#{shipperCode} ,UPPER(#{shipperName}) ,SUBSTRING(UPPER(#{shipperAddress}), 1, 60) ,SUBSTRING(UPPER(#{shipperAddress}), 61, 60) ,SUBSTRING(UPPER(#{shipperAddress}), 121, 60) ,SUBSTRING(UPPER(#{shipperAddress}), 181, 60) ,SUBSTRING(UPPER(#{shipperAddress}), 241, 60) ,#{shipperTel} ,#{shipperZipcode} ,#{shipperCountryCode} ,#{shipperStateCode} ,#{shipperPlaceCode} ,#{shipperPlace} ,#{shipperStreet} ,dbo.Cryptography(#{odJobNo}, #{shipperBusinessId}, 0) ,#{shipperAttnId} ,#{shipperAttn} ,#{shipperFax} ,#{consigneeCode} ,UPPER(#{consigneeName}) ,SUBSTRING(UPPER(#{consigneeAddress}), 1, 60) ,SUBSTRING(UPPER(#{consigneeAddress}), 61, 60) ,SUBSTRING(UPPER(#{consigneeAddress}), 121, 60) ,SUBSTRING(UPPER(#{consigneeAddress}), 181, 60) ,SUBSTRING(UPPER(#{consigneeAddress}), 241, 60) ,#{consigneeZipcode} ,#{consigneeCountryCode} ,#{consigneeStateCode} ,#{consigneePlaceCode} ,#{consigneePlace} ,#{consigneeStreet} ,dbo.Cryptography(#{odJobNo}, #{consigneeBusinessId}, 0) ,#{consigneeAttnId} ,#{consigneeAttn} ,#{consigneeFax} ,#{consigneeNameLoc} ,#{consigneeAddressLoc} ,#{inspectionType} ,#{ftaYn} ,#{ftaRemarks} ,#{remarks} ,#{agentRegNo} ,#{agentName} ,#{sellerRegNo} ,#{sellerName} ,#{salesBrokerRegNo} ,#{salesBrokerName} ,#{allowedItemCode} ,#{origCountry} ,#{dimWidth} ,#{dimHeight} ,#{dimLength} ,'WEB' ,#{updateUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{updateUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE())
,dbo.Cryptography(#{odJobNo}, #{consigneeHp}, 0) ,dbo.Cryptography(#{odJobNo}, #{consigneeTel}, 0) ,dbo.Cryptography(#{odJobNo}, #{customsId}, 0)
,#{consigneeHp} ,#{consigneeTel} ,#{customsId}
,#{consigneeLastName} ,#{consigneeFirstName} ,#{destDeliveryNo} ,#{forwardAgentCode} ,#{forwardAgentName} ,#{orderName} ,#{orderTel} ,#{orderAccount} ,#{ecmYn} )

/* OrderCustomerMapper.insertOrderAdditonal : Order Additional Insert */
INSERT INTO TB_ECM_OD_ADDITIONAL(
	OD_JOB_NO
	,LAST_POD_STATUS

	,CUSTOMS_ID_VERIFY
	,MBL_NO
	,HBL_NO
	,CD_TYPE
	,BL_TYPE_MH
)VALUES(
	#{odJobNo}
	,#{status}

	,'NV'
	,LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
	,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),'')))
	,#{cdType}
	,#{blTypeMh}
)

mapper.update:
/* OrderCustomerMapper.updateOrderAdditonal : Order Additional Update */
UPDATE TB_ECM_OD_ADDITIONAL SET
	   CUSTOMS_ID_VERIFY = CASE WHEN (#{customsId} IS NULL OR #{customsId} = '') THEN 'X' ELSE 'NV' END
	  ,MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
	  ,HBL_NO = LTRIM(RTRIM(REPLACE(#{hblNo},char(9),'')))
	  ,CD_TYPE = #{cdType}

	  ,SIMPLE_DOC_NO = null

WHERE OD_JOB_NO = #{odJobNo}

		/* OrderCustomerMapper.updateOrder : Order updateOrder */
		UPDATE TB_ECM_OD SET


    		  BOUND = #{bound}                                                                                              
    		  ,BOUND_TYPE = #{boundType}   
			  ,PO_DATE = CONVERT(DATE, #{poDate}, ${dateFormat})
			  ,PO_NO = LTRIM(RTRIM(#{poNo}))
			  ,MBL_NO = LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
			  ,HBL_NO = LTRIM(RTRIM(REPLACE(#{hblNo},char(9),'')))
			  ,CD_TYPE = #{cdType}
			  ,CD_USE_TYPE = #{cdUseType}
			  ,ECM_TYPE = #{ecmType}
			  ,ECM_BUY_TYPE = #{ecmBuyType}
			  ,PIECES = #{pieces}
			  ,PIECES_REAL = #{piecesReal}
			  ,GWT = #{gwt}
			  ,GWT_LBS = #{gwtLbs}
			  ,CURRENCY_CODE = #{currencyCode}
			  ,AMOUNT_CUR = #{amountCur}                          	
			  ,VWT = #{vwt} 

			  ,CBM = #{cbm} 
			  ,SHIPPER_NAME = UPPER(#{shipperName})
			  ,SHIPPER_ADDRESS = SUBSTRING(UPPER(#{shipperAddress}), 1, 60)
			  ,SHIPPER_ADDRESS_A = SUBSTRING(UPPER(#{shipperAddress}), 61, 60) 
			  ,SHIPPER_ADDRESS_B = SUBSTRING(UPPER(#{shipperAddress}), 121, 60) 
			  ,SHIPPER_ADDRESS_C = SUBSTRING(UPPER(#{shipperAddress}), 181, 60)
			  ,SHIPPER_ADDRESS_D = SUBSTRING(UPPER(#{shipperAddress}), 241, 60)
			  ,SHIPPER_TEL = #{shipperTel}
			  ,URL = #{url}
			  ,CONSIGNEE_NAME = UPPER(#{consigneeName})
			  ,CONSIGNEE_ADDRESS = SUBSTRING(UPPER(#{consigneeAddress}), 1, 60) 
			  ,CONSIGNEE_ADDRESS_A = SUBSTRING(UPPER(#{consigneeAddress}), 61, 60)
			  ,CONSIGNEE_ADDRESS_B = SUBSTRING(UPPER(#{consigneeAddress}), 121, 60)
			  ,CONSIGNEE_ADDRESS_C = SUBSTRING(UPPER(#{consigneeAddress}), 181, 60)
			  ,CONSIGNEE_ADDRESS_D = SUBSTRING(UPPER(#{consigneeAddress}), 241, 60)					  
			  ,CONSIGNEE_BUSINESS_ID = dbo.Cryptography(#{odJobNo}, #{consigneeBusinessId}, 0)
			  ,CONSIGNEE_NAME_LOC = #{consigneeNameLoc}
			  ,CONSIGNEE_ADDRESS_LOC = #{consigneeAddressLoc}				  
			  ,CONSIGNEE_ZIPCODE = #{consigneeZipcode}


			  ,SHIPPER_COUNTRY_CODE = #{shipperCountryCode}
			  ,SHIPPER_STREET = #{shipperStreet}
			  ,SHIPPER_PLACE = #{shipperPlace}
			  ,SHIPPER_STATE_CODE = #{shipperStateCode}
			  ,CONSIGNEE_COUNTRY_CODE = #{consigneeCountryCode}
			  ,CONSIGNEE_STREET = #{consigneeStreet}
			  ,CONSIGNEE_PLACE = #{consigneePlace}
			  ,CONSIGNEE_STATE_CODE = #{consigneeStateCode}

			  ,CUSTOMS_ID_TYPE = #{customsIdType}
			  ,DELIVERY_CODE = #{deliveryCode}
			  ,DELIVERY_NOTE = #{deliveryNote}
			  ,CB_CODE = #{cbCode}
			  ,CB_NAME = #{cbName}
			  ,CLEARANCE_VIOLATION_CODE = #{clearanceViolationCode}
			  ,CLEARANCE_VIOLATION_REASON = #{clearanceViolationReason}
			  ,FTA_YN = #{ftaYn}     
    		  ,FTA_REMARKS = #{ftaRemarks} 
    		  ,AGENT_REG_NO = #{agentRegNo}    
    		  ,COMMODITY_ITEM = UPPER(#{commodityItem})
    		  ,ALLOWED_ITEM_CODE = #{allowedItemCode}

    		  ,DIM_WIDTH = #{dimWidth}
    		  ,DIM_LENGTH = #{dimLength}
    		  ,DIM_HEIGHT = #{dimHeight}
			  ,UPDATE_USER_ID = #{updateUserId}
			  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())


			  ,CONSIGNEE_HP_ENC = dbo.Cryptography(#{odJobNo}, #{consigneeHp}, 0)
			  ,CONSIGNEE_TEL_ENC = dbo.Cryptography(#{odJobNo}, #{consigneeTel}, 0)
			  ,CUSTOMS_ID_ENC = dbo.Cryptography(#{odJobNo}, #{customsId}, 0)


			  ,CONSIGNEE_HP = #{consigneeHp}
			  ,CONSIGNEE_TEL = #{consigneeTel}
			  ,CUSTOMS_ID = #{customsId}


			  ,CONSIGNEE_LAST_NAME = #{consigneeLastName}
			  ,CONSIGNEE_FIRST_NAME = #{consigneeFirstName}
			  ,DEST_DELIVERY_NO = #{destDeliveryNo}
	            ,FORWARD_AGENT_CODE = #{forwardAgentCode}
	            ,FORWARD_AGENT_NAME = #{forwardAgentName}
	            ,ORDER_NAME = #{orderName}
	            ,ORDER_TEL = #{orderTel}
	            ,ORDER_ACCOUNT = #{orderAccount}
	            ,ECM_YN = #{ecmYn}
		WHERE OD_JOB_NO = #{odJobNo}

