/* OrderCustomerMapper.deleteSub : OrderSub initial */

UPDATE TB_ECM_OD
SET PARENT_OD_JOB_NO = ''
WHERE OD_JOB_NO IN (

	#{item.odJobNo}

)

/* OrderCustomerMapper.updateSub : OrderSub update */

UPDATE TB_ECM_OD
SET PARENT_OD_JOB_NO = #{odJobNo}
WHERE OD_JOB_NO IN (

	#{item.odJobNo}

)

mapper.select:
/* OrderCustomerMapper.dupOrderNo : OrderNo 중복체크 */
SELECT CASE WHEN COUNT(1) > 0 THEN 'Y' ELSE 'N' END 
FROM TB_ECM_OD
WHERE PO_NO = LTRIM(RTRIM(#{poNo}))

	AND OD_JOB_NO != #{odJobNo}

/* OrderCustomerMapper.selectBatchTargetCount : 일괄변경대상건수조회 */
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SELECT COUNT(*) CNT
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO

/* OrderCustomerMapper.selectPoInfo : Order 주문번호 조회 */
	SELECT PO_NO
	FROM TB_ECM_OD_PO_INFO
	WHERE OD_JOB_NO = #{odJobNo}

mapper.insert:
/* OrderCustomerMapper.insertMulti : Order 멀티(중량)화물 insert */

	INSERT INTO TB_ECM_OD_MULTI(
		   OD_JOB_NO
		  ,SEQ_NO_ID
		  ,DELIVERY_NO
		  ,DELIVERY_CODE
		  ,CUSTOMER_CODE
		  ,DELIVERY_NO_CHANGED
		  ,PAYMENT_GUBN
		  ,DELIVERY_FEE
		  ,PIECES
		  ,DIM_WIDTH
		  ,DIM_LENGTH
		  ,DIM_HEIGHT
		  ,VWT
		  ,RECIPIENT_NAME
		  ,RECEIPT_DATE
		  ,REMARKS
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,DELIVERER_USER_ID
		  ,DELIVERY_DATE
		  ,RETURN_DELIVERY_NO
		  ,RETURN_REQUEST_ID
		  ,RETURN_REQ_DATE
		  ,RETURN_DELIVERY_CODE
		  ,RETURN_END_DATE
		  ,RETURN_REG_DATE
		  ,DELIVERY_REG_DATE
		  ,DELIVERY_END_DATE
		  ,CONSIGNEE_NAME_LOC_M
		  ,CONSIGNEE_ADDRESS_LOC_M
		  ,CONSIGNEE_TEL_M
		  ,CONSIGNEE_ZIPCODE_M
	)VALUES

	(
		   #{odJobNo}
		  ,#{index} + 1
		  ,#{item.deliveryNo}
		  ,#{item.deliveryCode}
		  ,#{item.customerCode}
		  ,#{item.deliveryNoChanged}
		  ,#{item.paymentGubn}
		  ,#{item.deliveryFee}
		  ,#{item.pieces}
		  ,#{item.dimWidth}
		  ,#{item.dimLength}
		  ,#{item.dimHeight}
		  ,#{item.vwt}
		  ,#{item.recipientName}


		  ,NULL


		  ,CONVERT(DATE, #{item.receiptDate}, ${dateFormat})


